initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#anomaly-log-tbody");
  const detailArea = container.querySelector("#detail-area");
  let selectedLogId = null;
  let currentLogs = [];

  // 1. 再描画関数の定義
  function renderRows(rows) {
    currentLogs = rows;
    tbody.innerHTML = rows.map(r => {
      const detectionDate = r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP', {
        year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit'
      }) : '';

      const severityColor = r.重要度 === '高' ? '#ff4444' : r.重要度 === '中' ? '#ff8800' : '#888888';
      const statusColor = r.確認状況 === '未確認' ? '#ff4444' : r.確認状況 === '確認済み' ? '#ff8800' : '#22aa22';

      return `<tr data-id="${r.異常値検出ログID || r.id}" style="cursor: pointer;">
        <td>${detectionDate}</td>
        <td>${r.作業員名 || ''}</td>
        <td>${r.異常値種別 || ''}</td>
        <td>${r.検出項目 || ''}</td>
        <td>${r.検出値 || ''}</td>
        <td>${r.閾値 || ''}</td>
        <td><span style="color: ${severityColor}; font-weight: 500;">${r.重要度 || ''}</span></td>
        <td><span style="color: ${statusColor}; font-weight: 500;">${r.確認状況 || ''}</span></td>
        <td>${r.確認者名 || ''}</td>
        <td><button class="action-btn secondary detail-btn" data-id="${r.異常値検出ログID || r.id}">詳細</button></td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(5).then(rows => {
    if (rows) {
      renderRows(rows);
    }
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateStart = container.querySelector("#filter-date-start").value;
    const dateEnd = container.querySelector("#filter-date-end").value;
    const anomalyType = container.querySelector("#filter-anomaly-type").value;
    const severity = container.querySelector("#filter-severity").value;
    const workerName = container.querySelector("#filter-worker-name").value;
    const status = container.querySelector("#filter-status").value;

    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (dateStart && r.検出日時 && new Date(r.検出日時) < new Date(dateStart)) return false;
      if (dateEnd && r.検出日時 && new Date(r.検出日時) > new Date(dateEnd)) return false;
      if (anomalyType && r.異常値種別 !== anomalyType) return false;
      if (severity && r.重要度 !== severity) return false;
      if (workerName && (!r.作業員名 || !r.作業員名.includes(workerName))) return false;
      if (status && r.確認状況 !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. フィルタークリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#filter-date-start").value = '';
    container.querySelector("#filter-date-end").value = '';
    container.querySelector("#filter-anomaly-type").value = '';
    container.querySelector("#filter-severity").value = '';
    container.querySelector("#filter-worker-name").value = '';
    container.querySelector("#filter-status").value = '';

    window.aivicApi.list(5).then(rows => {
      if (rows) renderRows(rows);
    });
  });

  // 5. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const headers = ['検出日時', '作業員名', '異常値種別', '検出項目', '検出値', '閾値', '重要度', '確認状況', '確認者名', '対応メモ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.検出日時 || '',
        r.作業員名 || '',
        r.異常値種別 || '',
        r.検出項目 || '',
        r.検出値 || '',
        r.閾値 || '',
        r.重要度 || '',
        r.確認状況 || '',
        r.確認者名 || '',
        (r.対応メモ || '').replace(/"/g, '""')
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `異常値検出ログ_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  });

  // 6. 詳細表示・対応状況更新
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const row = e.target.closest("tr[data-id]");

    if (detailBtn || (row && !e.target.closest("button"))) {
      const logId = detailBtn ? detailBtn.dataset.id : row.dataset.id;
      selectedLogId = logId;

      const logData = currentLogs.find(r => (r.異常値検出ログID || r.id) === logId);
      if (!logData) return;

      // 詳細エリア表示
      detailArea.classList.remove("hidden");
      container.querySelector("#detail-target").textContent = 
        `${logData.検出対象テーブル || ''} - ${logData.作業員名 || ''}`;
      container.querySelector("#detail-anomaly").textContent = 
        `${logData.異常値種別 || ''}: ${logData.検出項目 || ''} = ${logData.検出値 || ''} (閾値: ${logData.閾値 || ''})`;
      container.querySelector("#detail-status").value = logData.確認状況 || '未確認';
      container.querySelector("#detail-memo").value = logData.対応メモ || '';

      // スクロール
      detailArea.scrollIntoView({ behavior: 'smooth' });
    }
  });

  // 7. 対応状況更新
  container.querySelector("#btn-update-status").addEventListener("click", async () => {
    if (!selectedLogId) return;

    const status = container.querySelector("#detail-status").value;
    const memo = container.querySelector("#detail-memo").value;

    const updated = await window.aivicApi.update(5, selectedLogId, {
      確認状況: status,
      対応メモ: memo,
      確認日時: new Date().toISOString(),
      確認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
    });

    if (updated) {
      // 一覧を再読み込み
      const rows = await window.aivicApi.list(5);
      if (rows) renderRows(rows);

      alert('対応状況を更新しました');
    }
  });

  // 8. 元記録確認
  container.querySelector("#btn-view-record").addEventListener("click", () => {
    if (!selectedLogId) return;

    const logData = currentLogs.find(r => (r.異常値検出ログID || r.id) === selectedLogId);
    if (logData && logData.検出対象テーブル === '作業記録') {
      window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
    }
  });
}
